const rows = async (f: string) => (await Bun.file(f).text()).trim().split("\n").slice(1).map(l => l.split(","));
const d = await rows("data/deploys.csv"), inc = await rows("data/incidents.csv");
const H = (a: string, b: string) => (Date.parse(b) - Date.parse(a)) / 36e5;
const med = (x: number[]) => { const s = [...x].sort((a, b) => a - b), m = s.length >> 1; return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };
const byM: Record<string, string[][]> = {};
for (const r of d) (byM[r[4].slice(0, 7)] ??= []).push(r);
const incM: Record<string, number[]> = {};
for (const r of inc) (incM[r[2].slice(0, 7)] ??= []).push(H(r[2], r[3]));
for (const [m, rs] of Object.entries(byM)) {
  const lt = rs.map(r => H(r[3], r[4])); const f = rs.filter(r => r[5]).length;
  console.log(m, rs.length, "lead med h", med(lt).toFixed(1), "fail", f, (100 * f / rs.length).toFixed(0) + "%", "restore h", (incM[m] ?? []).map(x => x.toFixed(1)).join(" "));
}
const lt = d.map(r => H(r[3], r[4]));
const ttr = inc.map(r => H(r[2], r[3]));
console.log("ALL", d.length, "lead med", med(lt).toFixed(1), "min", Math.min(...lt).toFixed(1), "max", Math.max(...lt).toFixed(1), "cfr", (100 * inc.length / d.length).toFixed(1), "ttr med", med(ttr).toFixed(2), "min", Math.min(...ttr).toFixed(2), "max", Math.max(...ttr).toFixed(2));
const days = H("2026-05-04T00:00:00Z", "2026-10-31T23:59:59Z") / 24;
console.log("days", days.toFixed(0), "per week", (d.length / days * 7).toFixed(2));
const h1 = d.slice(0, 34), h2 = d.slice(34);
for (const [n, s] of [["first34", h1], ["last35", h2]] as const) console.log(n, "lead med", med(s.map(r => H(r[3], r[4]))).toFixed(1), "fails", s.filter(r => r[5]).length);

